1	<?php
2	/**
3	 * Hromadne akce s objednavkami (formular ze seznamu objednavek).
4	 *
5	 * POST ids[] + action:
6	 *   storno   – stornuje vybrane objednavky
7	 *   paid     – oznaci jako zaplacene (parovani plateb z banky, 2016)
8	 *   shipped  – oznaci jako odeslane (hromadne odeslani balíku)
9	 */
10	
11	global $db;
12	legacy_db();
13	auth_require('obchod');
14	
15	$ids = isset($_POST['ids']) ? $_POST['ids'] : array();
16	$action = isset($_POST['action']) ? (string) $_POST['action'] : '';
17	
18	if (!is_array($ids) || count($ids) == 0) {
19	    flash('Nevybrali jste žádné objednávky', 'error');
20	    redirect(admin_url('orders'));
21	    return;
22	}
23	
24	$idList = ids_to_sql($ids);
25	
26	if ($action == 'storno') {
27	    // stornovat lze cokoliv krome dorucenych (2017: i odeslane, kdyz se balik vrati)
28	    $before = $db->query("SELECT id, status FROM orders WHERE id IN (" . $idList . ")");
29	    $n = $db->exec("UPDATE orders SET status = 'cancelled' WHERE id IN (" . $idList . ") AND status != 'delivered'");
30	    foreach ($before as $b) {
31	        if ($b['status'] != 'delivered') {
32	            audit_log('order', $b['id'], 'storno', array('from' => $b['status'], 'bulk' => true));
33	        }
34	    }
35	    // FIXME: rezervace ve skladu zustanou viset, viz StockReport::orphanReservations()
36	    flash('Stornováno objednávek: ' . $n);
37	} elseif ($action == 'paid') {
38	    $n = $db->exec("UPDATE orders SET status = 'paid' WHERE id IN (" . $idList . ") AND status = 'confirmed'");
39	    foreach ($ids as $oid) {
40	        audit_log('order', $oid, 'status', array('to' => 'paid', 'bulk' => true));
41	    }
42	    flash('Označeno jako zaplacené: ' . $n);
43	} elseif ($action == 'shipped') {
44	    $n = $db->exec("UPDATE orders SET status = 'shipped' WHERE id IN (" . $idList . ") AND status = 'paid'");
45	    foreach ($ids as $oid) {
46	        audit_log('order', $oid, 'status', array('to' => 'shipped', 'bulk' => true));
47	    }
48	    flash('Označeno jako odeslané: ' . $n);
49	} else {
50	    flash('Neznámá akce', 'error');
51	}
52	
53	cache_delete('dashboard_stats');
54	redirect(admin_url('orders'));
